INSERT INTO Tours (Name, StartDot, EndDot, Details, Tickets_Id, Transfers_Id, ImageTour, Price, Description, Separately,
                   Included, Program, Type, HotTour)
VALUES ('Московские каникулы', '2025-03-15', '2025-03-22',
        'Экскурсии по Москве, посещение Кремля, Третьяковской галереи', 1, 1, 'Image/Tours/moscow_tour.jpg', 32500,
        'Москва — сердце России, город с тысячелетней историей, где современные небоскребы соседствуют с древними монастырями, а шумные проспекты сменяются тихими арбатскими переулками. Это путешествие позволит вам прикоснуться к истории страны, увидеть главные достопримечательности столицы и почувствовать её неповторимую атмосферу. Вы побываете в Кремле, прогуляетесь по Красной площади, насладитесь шедеврами в Третьяковской галерее и увидите Москву с высоты Воробьевых гор. Москва удивит вас своим величием, гостеприимством и бесконечным разнообразием впечатлений.',
        'Авиаперелет (по желанию). Трансфер (по желанию). Виза (не требуется для граждан РФ). Дополнительные экскурсии. Питание (кроме завтраков)',
        'Проживание в отеле 4* в центре Москвы. Завтраки (шведский стол). Обзорная экскурсия по Москве. Экскурсия в Московский Кремль. Посещение Третьяковской галереи. Трансферы по программе. Услуги гида. Медицинская страховка',
        'День 1: Прибытие в Москву, трансфер, заселение в отель. Вечерняя обзорная экскурсия по вечерней Москве.; День 2: Завтрак. Экскурсия в Московский Кремль (территория, соборы, Ивановская площадь). Посещение Оружейной палаты. Прогулка по Александровскому саду.; День 3: Завтрак. Посещение Третьяковской галереи. Пешеходная экскурсия по Замоскворечью. Свободное время.; День 4: Завтрак. Экскурсия на Воробьевы горы и смотровую площадку. Посещение Новодевичьего монастыря.; День 5: Завтрак. Экскурсия на ВДНХ и прогулка по Останкинскому парку. Свободное время для шопинга.; День 6: Завтрак. Экскурсия в Коломенское - бывшую царскую усадьбу. Прощальный ужин в ресторане русской кухни.; День 7: Завтрак. Свободное время. Трансфер в аэропорт, вылет.;',
        'Экскурсионный'),
       ('Питер классический', '2025-03-20', '2025-03-25', 'Эрмитаж, Петергоф, Царское село', 2, 2,
        'Image/Tours/spb_tour.jpg', 89000,
        'Санкт-Петербург — культурная столица России, город мостов и каналов, дворцов и музеев, где каждый камень дышит историей. Северная Венеция очаровывает своей величественной архитектурой, разводными мостами и особым романтическим настроением. Вы увидите легендарный Эрмитаж с его богатейшей коллекцией мирового искусства, прогуляетесь по Летнему саду, посетите роскошные пригороды — Петергоф с его знаменитыми фонтанами и Царское село с Янтарной комнатой. Петербург откроет вам свои тайны и подарит незабываемые впечатления.',
        'Авиаперелет. Трансфер до отеля. Виза (не требуется для граждан РФ). Обеды и ужины. Фотосъемка в музеях. Экскурсии в пригороды (включены только Петергоф и Царское село)',
        'Проживание в отеле 5* в историческом центре. Завтраки. Входные билеты в Эрмитаж. Входные билеты в Петергоф. Входные билеты в Царское село (Екатерининский дворец с Янтарной комнатой). Обзорная экскурсия по городу. Экскурсия по рекам и каналам. Услуги профессионального гида. Трансферы по программе экскурсий. Медицинская страховка.',
        'День 1: Прибытие, трансфер, заселение. Обзорная экскурсия по городу: Невский проспект, Казанский собор, Дворцовая площадь.; День 2: Завтрак. Экскурсия в Эрмитаж (главный музейный комплекс). Прогулка по Дворцовой набережной.; День 3: Завтрак. Поездка в Петергоф. Осмотр Большого дворца и знаменитого парка с фонтанами. Возвращение в город.; День 4: Завтрак. Поездка в Царское село (г. Пушкин). Посещение Екатерининского дворца и Янтарной комнаты. Прогулка по Александровскому парку.; День 5: Завтрак. Экскурсия по рекам и каналам Петербурга. Посещение Петропавловской крепости. Свободное время. Трансфер в аэропорт, вылет.;',
        'Экскурсионный'),
       ('Казань за неделю', '2025-03-10', '2025-03-20', 'Кремль, Мечеть Кул-Шариф, Старо-Татарская слобода', 3, 3,
        'Image/Tours/kazan_tour.jpg', 60000,
        'Казань — столица Татарстана, уникальный город, где гармонично переплелись европейская и азиатская культуры, православие и ислам. Казанский Кремль, внесенный в список ЮНЕСКО, поражает соседством Благовещенского собора и мечети Кул-Шариф. Старо-Татарская слобода погружает в атмосферу купеческой Казани XIX века. Вы попробуете настоящий чак-чак, услышите звон колоколов и призыв муэдзина, прогуляетесь по пешеходной улице Баумана и почувствуете неповторимый колорит этого удивительного города.',
        'Авиаперелет. Трансфер. Обеды и ужины. Сувениры. Дополнительные экскурсии (например, в Свияжск или Раифский монастырь).',
        'Проживание в отеле 4*. Завтраки. Экскурсия по Казанскому Кремлю с посещением мечети Кул-Шариф. Экскурсия в Старо-Татарскую слободу. Посещение Благовещенского собора. Пешеходная экскурсия по улице Баумана. Услуги гида. Медицинская страховка.',
        'День 1: Прибытие, заселение. Вечерняя прогулка по Кремлевской набережной.; День 2: Завтрак. Экскурсия по Казанскому Кремлю: мечеть Кул-Шариф, Башня Сююмбике, Благовещенский собор.; День 3: Завтрак. Экскурсия в Старо-Татарскую слободу. Дегустация татарских национальных блюд (за доп. плату).; День 4: Завтрак. Пешеходная экскурсия по улице Баумана. Посещение дома Зинаиды Волконской. Свободное время.; День 5: Завтрак. Свободный день для самостоятельных прогулок или дополнительных экскурсий (рекомендуем Свияжск).; День 6: Завтрак. Посещение Национального музея Республики Татарстан. Прощальный ужин.; День 7: Завтрак. Трансфер в аэропорт, вылет.;',
        'Экскурсионный'),
       ('Сочи - лето круглый год', '2025-04-01', '2025-04-15', 'Красная поляна, Олимпийский парк, пляжный отдых', 4,
        4, 'Image/Tours/sochi_tour.jpg', 120000,
        'Сочи — жемчужина Черноморского побережья, уникальный курорт, где высокие заснеженные горы встречаются с теплым морем. Это место, где можно совместить пляжный отдых с активными приключениями. Олимпийское наследие города поражает своими масштабами. Вы подниметесь в горы Красной Поляны, прогуляетесь по Олимпийскому парку, увидите знаменитые стадионы и гоночную трассу «Сочи Автодром». Здесь вы сможете насладиться морским бризом, покататься на канатных дорогах и отведать сочинские мандарины.',
        'Авиаперелет. Трансфер из аэропорта. Обеды и ужины. Подъемники на курортах Красной Поляны. Экскурсии в Абхазию. Билеты в парки развлечений (Сочи Парк).',
        'Проживание в отеле 4* на первой береговой линии. Завтраки. Экскурсия в Олимпийский парк. Экскурсия на курорты Красной Поляны (с обзором). Посещение знаменитой Мацесты. Прогулка по набережной и в парке Ривьера. Услуги гида. Медицинская страховка.',
        'День 1: Прибытие, заселение, знакомство с отелем, отдых на пляже.; День 2: Завтрак. Экскурсия в Олимпийский парк: стадион Фишт, ледовый дворец, Сочи Автодром.; День 3: Завтрак. Поездка в Красную Поляну. Подъем на канатной дороге (за доп. плату), обед в горах.; День 4: Завтрак. Экскурсия к Мацесте и посещение дачи Сталина. Свободное время.; День 5: Завтрак. Морская прогулка на катере. Вечером — посещение Сочи Парка (опционально).; День 6: Завтрак. Свободный день для пляжного отдыха.; День 7: Завтрак. Свободное время. Трансфер в аэропорт, вылет.;',
        'Экскурсионный'),
       ('Екатеринбург деловой', '2025-03-25', '2025-03-28', 'Деловая программа + экскурсии по городу', 5, 5,
        'Image/Tours/ekb_tour.jpg', 25000,
        'Екатеринбург — столица Урала, мощный промышленный и деловой центр России, где кирпичная архитектура заводов соседствует с современными небоскребами. Город на границе Европы и Азии славится своим динамичным развитием и богатой историей, связанной с последними днями царской семьи. Эта программа идеально подходит для деловых людей, желающих совместить работу с знакомством с городом. Вы посетите деловые центры, проведете переговоры в комфортной обстановке, увидите место гибели царской семьи на Ганиной Яме и проведете встречу на границе частей света.',
        'Авиаперелет. Трансфер. Питание (кроме завтраков). Проживание (программа рассчитана на самостоятельное бронирование гостиницы)',
        'Организация деловых встреч и переговоров. Обзорная экскурсия по Екатеринбургу. Посещение Храма-на-Крови. Экскурсия на Ганину Яму (монастырь Царственных страстотерпцев). Посещение границы Европа-Азия. Аренда переговорной комнат. Услуги переводчика (при необходимости). Трансферы по деловой программе',
        'День 1: Прибытие, заселение. Деловая встреча. Обзорная экскурсия по городу: плотина городского пруда, набережная; День 2: Деловая программа (переговоры, встречи). Обед в деловом центре. Посещение Храма-на-Крови на месте расстрела царской семьи.; День 3: Деловая программа. Экскурсия на Ганину Яму. Вечерний ужин с партнерами.; День 4: Поездка на границу Европа-Азия. Фотосессия. Трансфер в аэропорт, вылет.;',
        'Экскурсионный');